:root {
  --ink: #24352a;
  --moss: #547449;
  --cream: #fffdf6;
  --sand: #e7ddbd;
  --leaf: #dbe8ce;
}

.cache-card {
  width: 440px;
  padding: 16px;
  border: 2px solid var(--moss);
  border-radius: 16px;
  background: var(--cream);
  color: var(--ink);
}

.top-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.acorn {
  font-size: 25px;
}

.state {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--leaf);
  color: var(--moss);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

h1 {
  margin: 10px 0 3px;
  font-size: 21px;
  line-height: 1.1;
}

p {
  margin: 0 0 14px;
  color: var(--moss);
  font-size: 14px;
}

footer {
  border-top: 1px solid var(--sand);
  padding-top: 12px;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: var(--moss);
  color: var(--cream);
  font-size: 13px;
  font-weight: 700;
}
